# Construct the test output: connect the two gray endpoints through each 3-cell gate.
grid = [[4]*30 for _ in range(30)]
for r, cs in [(4,(8,9,10)),(12,(14,15,16)),(19,(9,10,11))]:
    grid[r] = [6]*30
    for c in cs: grid[r][c] = 3
# Original endpoints
grid[1][19] = 5
grid[25][9] = 5
# Path, inclusive
cells = set()
cells |= {(r,19) for r in range(1,4)}
cells |= {(3,c) for c in range(9,20)}
cells |= {(r,9) for r in range(4,12)}
cells |= {(11,c) for c in range(9,16)}
cells |= {(r,15) for r in range(12,19)}
cells |= {(18,c) for c in range(10,16)}
cells |= {(r,10) for r in range(19,26)}
cells |= {(25,c) for c in range(9,11)}
for r,c in cells: grid[r][c]=5
print('\n'.join(' '.join(map(str,row)) for row in grid))

# Show only non-background cells by row to audit the proposed path.
for i,row in enumerate(grid):
    print(i, [(j,v) for j,v in enumerate(row) if v != 4 and v != 6])
